     6  #define READ(x, i) r_read_be32 ((x) + (i)); (i) += 4;
     7
     8  R_IPI RBinAddr *r_bflt_get_entry(struct r_bin_bflt_obj *bin) {
     9          RBinAddr *addr = R_NEW0 (RBinAddr);
    10          if (addr && bin && bin->hdr) {
    11                  addr->paddr = bin->hdr->entry;
    12          }
    13          return addr;
    14  }
    15
    16  static int bflt_init_hdr(struct r_bin_bflt_obj *bin) {
    17          ut8 bhdr[BFLT_HDR_SIZE] = {0};
    18
    19          int len = r_buf_read_at (bin->b, 0, bhdr, BFLT_HDR_SIZE);
    20          if (len < 1) {
    21                  R_LOG_WARN ("read bFLT hdr failed");
    22                  goto fail;
    23          }
    24
    25          if (strncmp ((const char *)bhdr, "bFLT", 4)) {
    26                  R_LOG_WARN ("wrong magic number in bFLT file");
    27                  goto fail;
    28          }
    29          struct bflt_hdr *p_hdr = R_NEW0 (struct bflt_hdr);
    30          if (!p_hdr) {
    31                  R_LOG_WARN ("couldn't allocate memory");
    32                  goto fail;
    33          }
    34
    35          int i = 4;
    36          p_hdr->rev = READ (bhdr, i);
    37          p_hdr->entry = READ (bhdr, i);
    38          p_hdr->data_start = READ (bhdr, i);
    39          p_hdr->data_end = READ (bhdr, i);
    40          p_hdr->bss_end = READ (bhdr, i);
    41          p_hdr->stack_size = READ (bhdr, i);
    42          p_hdr->reloc_start = READ (bhdr, i);
    43          p_hdr->reloc_count = READ (bhdr, i);
    44          p_hdr->flags = READ (bhdr, i);
    45          p_hdr->build_date = READ (bhdr, i);
    46
    47          if (p_hdr->rev != FLAT_VERSION) {
    48                  R_LOG_WARN ("only v4 is supported!");
    49                  R_FREE (p_hdr);
    50                  goto fail;
    51          }
    52          bin->hdr = p_hdr;
    53          return true;
    54  fail:
    55          return false;
    56  }
    57
    58  static bool r_bin_bflt_init(RBinBfltObj *obj, RBuffer *buf) {
    59          obj->b = r_buf_ref (buf);
    60          obj->size = r_buf_size (buf);
    61          obj->endian = false;
    62          obj->reloc_table = NULL;
    63          obj->got_table = NULL;
    64          obj->n_got = 0;
    65          obj->hdr = NULL;
    66          if (!bflt_init_hdr (obj)) {
    67                  return false;
    68          }
    69          return true;
    70  }
    71
    72  R_IPI void r_bin_bflt_free(RBinBfltObj *o) {
    73          if (o) {
    74                  r_list_free (o->relocs_list);
    75                  R_FREE (o->hdr);
    76                  r_buf_free (o->b);
    77                  free (o);
    78          }
    79  }
    80
    81  R_IPI RBinBfltObj *r_bin_bflt_new_buf(RBuffer *buf) {
    82          R_RETURN_VAL_IF_FAIL (buf, NULL);
    83          RBinBfltObj *o = R_NEW0 (RBinBfltObj);
    84          if (o && r_bin_bflt_init (o, buf)) {
    85                  return o;
    86          }
    87          r_bin_bflt_free (o);
    88          return NULL;
    89  }

