     1  /* radare - LGPL - Copyright 2016-2022 - Oscar Salvador */
     2
     3  #ifndef BFLT_H
     4  #define BFLT_H
     5
     6  #include <r_util.h>
     7  #include <r_lib.h>
     8  #include <r_bin.h>
     9
    10  /* Version 4 */
    11  #define FLAT_VERSION            0x00000004L
    12  #define FLAT_FLAG_RAM           0x1     /* load program entirely into RAM */
    13  #define FLAT_FLAG_GOTPIC        0x2     /* program is PIC with GOT */
    14  #define FLAT_FLAG_GZIP          0x4     /* all but the header is compressed */
    15  #define FLAT_FLAG_GZDATA        0x8     /* only data/relocs are compressed (for XIP) */
    16  #define FLAT_FLAG_KTRACE        0x10    /* output useful kernel trace for debugging */
    17
    18  typedef struct bflt_hdr {
    19          ut8 magic[4];
    20          ut32 rev;
    21          ut32 entry;
    22          ut32 data_start;
    23          ut32 data_end;
    24          ut32 bss_end;
    25          ut32 stack_size;
    26          ut32 reloc_start;
    27          ut32 reloc_count;
    28          ut32 flags;
    29          ut32 build_date;
    30          ut32 filler[5];
    31  } RBinBfltHeader;
    32
    33  typedef struct reloc_struct_t {
    34          ut32 addr_to_patch;
    35          ut32 data_offset;
    36  } RBinBfltReloc;
    37
    38  typedef struct r_bin_bflt_obj {
    39          RBinBfltHeader *hdr;
    40          RBinBfltReloc *reloc_table;
    41          RBinBfltReloc *got_table;
    42          RList *relocs_list;
    43          RBuffer *b;
    44          ut8 endian;
    45          size_t size;
    46          ut32 n_got;
    47  } RBinBfltObj;
    48
    49  #define BFLT_HDR_SIZE sizeof (RBinBfltHeader)
    50  #define VALID_GOT_ENTRY(x) (x != UT32_MAX)
    51
    52  R_IPI RBinAddr *r_bflt_get_entry(RBinBfltObj *bin);
    53  R_IPI RBinBfltObj *r_bin_bflt_new_buf(RBuffer *buf);
    54  R_IPI void r_bin_bflt_free(RBinBfltObj *obj);
    55
    56  #endif

