     1  /* radare - LGPL - Copyright 2016-2024 - Oscar Salvador */
     2
     3  #include <r_bin.h>
     4  #include <r_io.h>
     5  #include "bflt/bflt.h"
     6
     7  static bool load(RBinFile *bf, RBuffer *buf, ut64 loadaddr) {
     8          bf->bo->bin_obj = r_bin_bflt_new_buf (buf);
     9          return bf->bo->bin_obj != NULL;
    10  }
    11
    12  static RList *entries(RBinFile *bf) {
    13          RList *ret = r_list_newf (free);
    14          if (ret) {
    15                  struct r_bin_bflt_obj *obj = (struct r_bin_bflt_obj *) R_UNWRAP3 (bf, bo, bin_obj);
    16                  RBinAddr *ptr = r_bflt_get_entry (obj);
    17                  if (ptr) {
    18                          r_list_append (ret, ptr);
    19                  }
    20          }
    21          return ret;
    22  }
    23
    24  static void __patch_reloc(RIOBind *iob, ut32 addr_to_patch, ut32 data_offset) {
    25          ut8 val[4] = { 0 };
    26          r_write_le32 (val, data_offset);
    27          iob->overlay_write_at (iob->io, addr_to_patch, val, sizeof (val));
    28  }
    29
    30  static int search_old_relocation(struct reloc_struct_t *reloc_table, ut32 addr_to_patch, int n_reloc) {
    31          int i;
    32          for (i = 0; i < n_reloc; i++) {
    33                  if (addr_to_patch == reloc_table[i].data_offset) {
    34                          return i;
    35                  }
    36          }
    37          return -1;
    38  }
    39
    40  static RList *patch_relocs(RBinFile *bf) {
    41          R_RETURN_VAL_IF_FAIL (bf && bf->rbin && bf->rbin->iob.io, NULL);
    42          struct r_bin_bflt_obj *bin = NULL;
    43          RBin *b = bf->rbin;
    44          RBinObject *obj = r_bin_cur_object (b);
    45          if (!obj) {
    46                  return NULL;
    47          }
    48          bin = obj->bin_obj;
    49          RList *list = r_list_newf ((RListFree) free);
    50          if (!list) {
    51                  return NULL;
    52          }
    53          if (bin->got_table) {
    54                  struct reloc_struct_t *got_table = bin->got_table;
    55                  int i;
    56                  for (i = 0; i < bin->n_got; i++) {
    57                          __patch_reloc (&b->iob, got_table[i].addr_to_patch,
    58                                  got_table[i].data_offset);
    59                          RBinReloc *reloc = R_NEW0 (RBinReloc);
    60                          if (reloc) {
    61                                  reloc->type = R_BIN_RELOC_32;
    62                                  reloc->paddr = got_table[i].addr_to_patch;
    63                                  reloc->vaddr = reloc->paddr;
    64                                  r_list_append (list, reloc);
    65                          }
    66                  }
    67                  R_FREE (bin->got_table);
    68          }
    69
    70          if (bin->reloc_table) {
    71                  struct reloc_struct_t *reloc_table = bin->reloc_table;
    72                  int i = 0;
    73                  for (i = 0; i < bin->hdr->reloc_count; i++) {
    74                          int found = search_old_relocation (reloc_table,
    75                                  reloc_table[i].addr_to_patch, bin->hdr->reloc_count);
    76                          if (found != -1) {
    77                                  __patch_reloc (&b->iob, reloc_table[found].addr_to_patch,
    78                                          reloc_table[i].data_offset);
    79                          } else {
    80                                  __patch_reloc (&b->iob, reloc_table[i].addr_to_patch,
    81                                          reloc_table[i].data_offset);
    82                          }
    83                          RBinReloc *reloc = R_NEW0 (RBinReloc);
    84                          if (reloc) {
    85                                  reloc->type = R_BIN_RELOC_32;
    86                                  reloc->paddr = reloc_table[i].addr_to_patch;
    87                                  reloc->vaddr = reloc->paddr;
    88                                  r_list_append (list, reloc);
    89                          }
    90                  }
    91                  R_FREE (bin->reloc_table);
    92          }
    93          return list;
    94  }
    95
    96  static ut32 get_ngot_entries(struct r_bin_bflt_obj *obj) {
    97          ut32 data_size = obj->hdr->data_end - obj->hdr->data_start;
    98          ut32 i = 0, n_got = 0;
    99          if (data_size > obj->size) {
   100                  return 0;
   101          }
   102          for (; i < data_size; i += 4, n_got++) {
   103                  ut32 entry, offset = obj->hdr->data_start;
   104                  if (offset + i + sizeof (ut32) > obj->size ||
   105                      offset + i + sizeof (ut32) < offset) {
   106                          return 0;
   107                  }
   108                  int len = r_buf_read_at (obj->b, offset + i, (ut8 *) &entry,
   109                          sizeof (ut32));
   110                  if (len != sizeof (ut32)) {
   111                          return 0;
   112                  }
   113                  if (!VALID_GOT_ENTRY (entry)) {
   114                          break;
   115                  }
   116          }
   117          return n_got;
   118  }
   119
   120  static RList *relocs(RBinFile *bf) {
   121          struct r_bin_bflt_obj *obj = (struct r_bin_bflt_obj *) bf->bo->bin_obj;
   122          if (obj->relocs_list) {
   123                  return r_list_clone (obj->relocs_list, NULL);
   124          }
   125          RList *list = r_list_newf ((RListFree) free);
   126          obj->relocs_list = list;
   127          ut32 i, len, n_got, amount;
   128          if (!list || !obj) {
   129                  r_list_free (list);
   130                  return NULL;
   131          }
   132          if (obj->hdr->flags & FLAT_FLAG_GOTPIC) {
   133                  n_got = get_ngot_entries (obj);
   134                  if (n_got) {
   135                          if (n_got > UT32_MAX / sizeof (struct reloc_struct_t)) {
   136                                  goto out_error;
   137                          }
   138                          amount = n_got * sizeof (struct reloc_struct_t);
   139                          struct reloc_struct_t *got_table = calloc (1, amount);
   140                          if (got_table) {
   141                                  ut32 offset = 0;
   142                                  for (i = 0; i < n_got; offset += 4, i++) {
   143                                          ut32 got_entry;
   144                                          if (obj->hdr->data_start + offset + 4 > obj->size ||
   145                                              obj->hdr->data_start + offset + 4 < offset) {
   146                                                  break;
   147                                          }
   148                                          len = r_buf_read_at (obj->b, obj->hdr->data_start + offset,
   149                                                  (ut8 *) &got_entry, sizeof (ut32));
   150                                          if (!VALID_GOT_ENTRY (got_entry) || len != sizeof (ut32)) {
   151                                                  break;
   152                                          }
   153                                          got_table[i].addr_to_patch = got_entry;
   154                                          got_table[i].data_offset = got_entry + BFLT_HDR_SIZE;
   155                                  }
   156                                  obj->n_got = n_got;
   157                                  obj->got_table = got_table;
   158                          }
   159                  }
   160          }
   161
   162          if (obj->hdr->reloc_count > 0) {
   163                  ut32 n_reloc = obj->hdr->reloc_count;
   164                  if (n_reloc > UT32_MAX / sizeof (struct reloc_struct_t)) {
   165                          goto out_error;
   166                  }
   167                  amount = n_reloc * sizeof (struct reloc_struct_t);
   168                  struct reloc_struct_t *reloc_table = calloc (1, amount);
   169                  if (!reloc_table) {
   170                          goto out_error;
   171                  }
   172                  amount = n_reloc * sizeof (ut32);
   173                  ut32 *reloc_pointer_table = calloc (1, amount);
   174                  if (!reloc_pointer_table) {
   175                          free (reloc_table);
   176                          goto out_error;
   177                  }
   178                  if (obj->hdr->reloc_start + amount > obj->size ||
   179                      obj->hdr->reloc_start + amount < amount) {
   180                          free (reloc_table);
   181                          free (reloc_pointer_table);
   182                          goto out_error;
   183                  }
   184                  len = r_buf_read_at (obj->b, obj->hdr->reloc_start,
   185                          (ut8 *) reloc_pointer_table, amount);
   186                  if (len != amount) {
   187                          free (reloc_table);
   188                          free (reloc_pointer_table);
   189                          goto out_error;
   190                  }
   191                  for (i = 0; i < n_reloc; i++) {
   192                          // XXX it doesn't take endian as consideration when swapping
   193                          ut32 reloc_offset =
   194                                  r_swap_ut32 (reloc_pointer_table[i]) +
   195                                  BFLT_HDR_SIZE;
   196
   197                          if (reloc_offset < obj->hdr->bss_end && reloc_offset < obj->size) {
   198                                  ut32 reloc_fixed, reloc_data_offset;
   199                                  if (reloc_offset + sizeof (ut32) > obj->size ||
   200                                      reloc_offset + sizeof (ut32) < reloc_offset) {
   201                                          free (reloc_table);
   202                                          free (reloc_pointer_table);
   203                                          goto out_error;
   204                                  }
   205                                  len = r_buf_read_at (obj->b, reloc_offset,
   206                                          (ut8 *) &reloc_fixed,
   207                                          sizeof (ut32));
   208                                  if (len != sizeof (ut32)) {
   209                                          eprintf ("problem while reading relocation entries\n");
   210                                          free (reloc_table);
   211                                          free (reloc_pointer_table);
   212                                          goto out_error;
   213                                  }
   214                                  reloc_data_offset = r_swap_ut32 (reloc_fixed) + BFLT_HDR_SIZE;
   215                                  reloc_table[i].addr_to_patch = reloc_offset;
   216                                  reloc_table[i].data_offset = reloc_data_offset;
   217
   218                                  RBinReloc *reloc = R_NEW0 (RBinReloc);
   219                                  if (reloc) {
   220                                          reloc->type = R_BIN_RELOC_32;
   221                                          reloc->paddr = reloc_table[i].addr_to_patch;
   222                                          reloc->vaddr = reloc->paddr;
   223                                          r_list_append (list, reloc);
   224                                  }
   225                          }
   226                  }
   227                  free (reloc_pointer_table);
   228                  obj->reloc_table = reloc_table;
   229          }
   230          return list;
   231  out_error:
   232          r_list_free (list);
   233          return NULL;
   234  }
   235
   236  static RBinInfo *info(RBinFile *bf) {
   237          RBinInfo *info = R_NEW0 (RBinInfo);
   238          if (info) {
   239                  struct r_bin_bflt_obj *obj = R_UNWRAP3 (bf, bo, bin_obj);
   240                  info->file = bf->file? strdup (bf->file): NULL;
   241                  info->rclass = strdup ("bflt");
   242                  info->bclass = strdup ("bflt" );
   243                  info->type = strdup ("bFLT (Executable file)");
   244                  info->os = strdup ("Linux");
   245                  info->subsystem = strdup ("Linux");
   246                  info->arch = strdup ("arm");
   247                  info->big_endian = obj? obj->endian: R_SYS_ENDIAN_LITTLE;
   248                  info->bits = 32;
   249                  info->has_va = false;
   250                  info->dbg_info = 0;
   251                  info->machine = strdup ("unknown");
   252          }
   253          return info;
   254  }
   255
   256  static bool check(RBinFile *bf, RBuffer *buf) {
   257          ut8 tmp[4] = {0};
   258          int r = r_buf_read_at (buf, 0, tmp, sizeof (tmp));
   259          return r == sizeof (tmp) && !memcmp (tmp, "bFLT", 4);
   260  }
   261
   262  static void destroy(RBinFile *bf) {
   263          r_bin_bflt_free (bf->bo->bin_obj);
   264  }
   265
   266  RBinPlugin r_bin_plugin_bflt = {
   267          .meta = {
   268                  .name = "bflt",
   269                  .author = "Oscar Salvador",
   270                  .desc = "bFLT format r_bin plugin",
   271                  .license = "LGPL-3.0-only",
   272          },
   273          .load = &load,
   274          .destroy = &destroy,
   275          .check = &check,
   276          .entries = &entries,
   277          .info = &info,
   278          .relocs = &relocs,
   279          .patch_relocs = &patch_relocs,
   280  };
   281
   282  #ifndef R2_PLUGIN_INCORE
   283  R_API RLibStruct radare_plugin = {
   284          .type = R_LIB_TYPE_BIN,
   285          .data = &r_bin_plugin_bflt,
   286          .version = R2_VERSION
   287  };
